import { lazy } from 'react'
import posts from 'virtual:posts'

// metadata for every post, newest first. Generated by plugins/posts.js
export { posts }

// each post body is its own chunk, only downloaded when the post is opened
const modules = import.meta.glob('/content/posts/*.mdx')
const components = Object.fromEntries(
  Object.entries(modules).map(([file, load]) => [
    file.match(/(\d+)\.mdx$/)[1],
    lazy(load),
  ])
)

export function getPost(slug) {
  const metadata = posts.find(post => String(post.id) === slug)
  if (!metadata || !components[slug]) return null
  return { metadata, Post: components[slug] }
}

export function formatDate(date, includeRelative = false) {
  let currentDate = new Date()
  if (!date.includes('T')) {
    date = `${date}T00:00:00`
  }
  let targetDate = new Date(date)

  let yearsAgo = currentDate.getFullYear() - targetDate.getFullYear()
  let monthsAgo = currentDate.getMonth() - targetDate.getMonth()
  let daysAgo = currentDate.getDate() - targetDate.getDate()

  let formattedDate = ''

  if (yearsAgo > 0) {
    formattedDate = `${yearsAgo}y ago`
  } else if (monthsAgo > 0) {
    formattedDate = `${monthsAgo}mo ago`
  } else if (daysAgo > 0) {
    formattedDate = `${daysAgo}d ago`
  } else {
    formattedDate = 'Today'
  }

  let fullDate = targetDate.toLocaleString('en-us', {
    month: 'long',
    day: 'numeric',
    year: 'numeric',
  })

  if (!includeRelative) {
    return fullDate
  }

  return `${fullDate} (${formattedDate})`
}
